docx_records = records.filtered(
    lambda d: d.mimetype == "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    or (d.name or "").strip().lower().endswith(".docx")
)
if not docx_records:
    raise UserError("Sélectionnez un fichier Word (.docx) pour afficher son aperçu.")
action = {
    "type": "ir.actions.act_url",
    "url": "/docx_preview/%s" % docx_records[0].id,
    "target": "new",
}
